use base64::Engine;
use base64::prelude::BASE64_STANDARD;
use ruffle_core::backend::storage::StorageBackend;
use web_sys::Storage;
use std::cell::Cell;

const PRESET_SAVE_BASE64: &str = "";

pub struct LocalStorageBackend {
    storage: Storage,
    preset_save_consumed: Cell<bool>,
}

impl LocalStorageBackend {
    pub(crate) fn new(storage: Storage) -> Self {
        LocalStorageBackend {
            storage,
            preset_save_consumed: Cell::new(false),
        }
    }
}

impl StorageBackend for LocalStorageBackend {
    fn get(&self, name: &str) -> Option<Vec<u8>> {
        // Automatically inject the supplied SOL the first time Ruffle asks
        // for a SharedObject whose name ends in "/so".
        //
        // This bypasses browser localStorage for the initial load, so the
        // preset cannot be missed because of origin/key/path differences.
        if !self.preset_save_consumed.get() && name.ends_with("/so") {
            if let Ok(data) = BASE64_STANDARD.decode(PRESET_SAVE_BASE64) {
                self.preset_save_consumed.set(true);
                return Some(data);
            }
        }

        if let Ok(Some(data)) = self.storage.get(name)
            && let Ok(data) = BASE64_STANDARD.decode(data)
        {
            Some(data)
        } else {
            None
        }
    }

    fn put(&mut self, name: &str, value: &[u8]) -> bool {
        self.storage
            .set(name, &BASE64_STANDARD.encode(value))
            .is_ok()
    }

    fn remove_key(&mut self, name: &str) {
        let _ = self.storage.delete(name);
    }
}
